<?php
namespace App\Services; use App\Models\{ProviderApplication,Provider,User,Role}; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException;
class ProviderApplicationService { public function apply(User $user,array $d):ProviderApplication {if(ProviderApplication::where('user_id',$user->id)->where('status','PENDING')->exists()||Provider::where('user_id',$user->id)->exists()) throw ValidationException::withMessages(['application'=>'An active provider application already exists.']); return ProviderApplication::create($d+['user_id'=>$user->id,'id'=>(string)Str::uuid(),'status'=>'PENDING']);} public function approve(ProviderApplication $a,User $admin):Provider { if($a->status!=='PENDING') throw ValidationException::withMessages(['application'=>'Application is no longer pending.']); $p=Provider::create(['user_id'=>$a->user_id,'category_id'=>$a->category_id,'bio'=>$a->bio,'experience_years'=>$a->experience_years,'location'=>$a->location,'verification_status'=>'VERIFIED','approved_at'=>now()]); $a->update(['status'=>'APPROVED','reviewed_by'=>$admin->id,'reviewed_at'=>now()]); $role=Role::where('name','PROVIDER')->first(); if($role&&!$p->user->roles()->whereKey($role->id)->exists())$p->user->roles()->attach($role->id); return $p;} public function reject(ProviderApplication $a,User $admin,string $reason):ProviderApplication {if($a->status!=='PENDING') throw ValidationException::withMessages(['application'=>'Application is no longer pending.']);$a->update(['status'=>'REJECTED','reviewed_by'=>$admin->id,'reviewed_at'=>now(),'rejection_reason'=>$reason]);return $a;} }
